<template>
  <div class="settings-hub" data-test="settings-hub">
    <div class="hub-header">
      <h2 class="hub-title">{{ $t('settings_overview') || 'Settings Overview' }}</h2>
      <p class="hub-subtitle">
        {{ $t('settings_overview_desc') || 'Manage your organization settings and configuration.' }}
      </p>
    </div>

    <!-- Quick Links -->
    <div class="quick-links-section" v-if="quickLinks.length > 0">
      <h3 class="section-title">{{ $t('quick_links') || 'Quick Links' }}</h3>
      <div class="quick-links-grid">
        <div
          v-for="link in quickLinks"
          :key="link.route"
          class="quick-link-card"
          @click="$router.push(link.route)"
        >
          <!-- <q-icon :name="link.icon" size="24px" color="primary" /> -->
           
          <Icon :icon="link.icon" width="24" height="24" class="text-primary" />
          <div class="quick-link-info">
            <span class="quick-link-title">{{ $t(link.translate) }}</span>
            <span class="quick-link-desc">{{ $t(link.tooltip) }}</span>
          </div>
          <q-icon name="chevron_right" size="20px" color="grey-5" />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">

import { defineComponent } from 'vue';
import { useSettingsNavigationStore } from 'src/store/settings-navigation';
import { isSupplierUser, getSupplierDetailsRoute } from 'src/utils/UserDetails';

export default defineComponent({
  name: 'SettingsHub',
  components: {

  },

  setup() {
    const navStore = useSettingsNavigationStore();
    return { navStore };
  },

  computed: {
    quickLinks() {
      // Suppliers get a filtered set (Users + Supplier Details); everyone else
      // gets the standard admin quick links.
      if (isSupplierUser()) {
        return this.navStore.getSupplierQuickLinks(this.$t, {
          supplierDetailsRoute: getSupplierDetailsRoute(),
        });
      }
      return this.navStore.getQuickLinks(this.$t);
    },
  },
});
</script>

